contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to put some funds, then try to Collect an amount. The rule:
    // if Collect does not revert then the holder's public balance decreases by exactly _am
    // and the contract's Ether balance decreases by exactly _am.
    function run(uint _lockTime, uint _am, uint putAmount) public payable {
        require(address(this).balance >= putAmount);
        // ensure MinSum is not preventing collection by setting it low before initializing
        // call SetMinSum (allowed before Initialized)
        c.SetMinSum(0);
        // prepare: deposit putAmount into c from this contract
        c.Put{value: putAmount}(_lockTime);

        // read before-values via public getters
        uint beforeHolderBalance = c.Acc(address(this)).balance;
        uint beforeContractBal = address(c).balance;

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterHolderBalance = c.Acc(address(this)).balance;
        uint afterContractBal = address(c).balance;

        // If Collect succeeded (did not revert) then the holder's balance must have decreased by exactly _am
        // and contract balance must have decreased by exactly _am. If Collect reverted then no guarantee, so assert only forces the implication.
        assert(reverted || (beforeHolderBalance >= _am && beforeHolderBalance - afterHolderBalance == _am && beforeContractBal - afterContractBal == _am));
    }

    receive() external payable {}
}

