contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take inputs for a lock time and an amount to send to Put. The test calls Put (directly)
    // and checks that the holder balance recorded by the public getter Acc(address(this)).balance
    // did not decrease as a result (it must be >= the prior balance, ensuring Put cannot reduce balance).
    function run(uint _lockTime, uint putAmount) public payable {
        require(address(this).balance >= putAmount);

        // Read the holder balance before the deposit via public getter
        (, uint beforeBalance) = c.Acc(address(this));

        // Call Put with value putAmount
        c.Put{value: putAmount}(_lockTime);

        // Read the holder balance after the deposit
        (, uint afterBalance) = c.Acc(address(this));

        // General invariant: after calling Put with some value, the recorded balance for this holder
        // is at least the previous recorded balance (Put must not decrease balance).
        assert(afterBalance >= beforeBalance);
    }

    receive() external payable {}
}

