contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes parameters to drive Put and Collect. We act as the same address (this contract)
    // amountPut funds the contract via Put (or fallback), lock adds to unlockTime, collectAmt attempts Collect.
    function run(uint lockAdd, uint amountPut, uint collectAmt) public payable {
        require(address(this).balance >= amountPut, "not enough ether to put");

        // Record contract-level and holder-level before values using public getters
        uint beforeCbal = address(c).balance;
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Make a Put call sending Ether amountPut and adding lockAdd to lock time
        c.Put{value: amountPut}(lockAdd);

        // Record after Put, before Collect values
        uint midCbal = address(c).balance;
        (uint midUnlock, uint midBalance) = c.Acc(address(this));

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Record after Collect values
        uint afterCbal = address(c).balance;
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // If Collect succeeded (did not revert) then it must have reduced the holder balance by collectAmt
        // and reduced the contract balance by collectAmt. Otherwise balances remain unchanged from mid state.
        assert(
            // Case: collect reverted -> balances unchanged
            (reverted && afterBalance == midBalance && afterCbal == midCbal)
            ||
            // Case: collect succeeded -> holder balance decreased by collectAmt and contract balance decreased by collectAmt
            (!reverted && midBalance >= collectAmt && afterBalance + collectAmt == midBalance && afterCbal + collectAmt == midCbal)
        );
    }

    // Allow receiving ETH so Put can be funded via this contract balance
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run drives Put then Collect as the same caller (this contract). We pass amounts and lock.
    function run(uint lockAdd, uint amountPut, uint collectAmt) public payable {
        // Ensure this test contract has enough Ether to fund the Put call
        require(address(this).balance >= amountPut);

        // Read holder state before any operations
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Perform Put sending amountPut wei
        c.Put{value: amountPut}(lockAdd);

        // Read holder state just before Collect
        (uint midUnlock, uint midBalance) = c.Acc(address(this));

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read holder state after Collect
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // If Collect succeeded then afterBalance == midBalance - collectAmt (only when midBalance >= collectAmt and midBalance >= c.MinSum() and block.timestamp>unlock), otherwise afterBalance == midBalance.
        // We cannot directly observe block.timestamp conditions or MinSum here, so express the general consequence observable: success implies decrease by collectAmt; failure implies no change.
        assert(
            (reverted && afterBalance == midBalance)
            ||
            (!reverted && afterBalance + collectAmt == midBalance)
        );
    }

    // Allow receiving ETH so Put can be funded via this contract balance
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test Put behavior: sending Ether with Put must not decrease the holder's stored balance
    // and address(c).balance must increase by exactly the sent amount. We also capture reverts.
    function run(uint lockAdd, uint amountPut) public payable {
        // Ensure this contract has enough Ether to send amountPut
        require(address(this).balance >= amountPut);

        // Read holder state and contract balance before
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        // Call Put and record whether it reverted
        bool reverted;
        try c.Put{value: amountPut}(lockAdd) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read holder state and contract balance after
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // General rule:
        // - If Put reverted, c's balance and recorded holder balance are unchanged.
        // - If Put succeeded, recorded holder balance did not decrease (afterBalance >= beforeBalance),
        //   and the on-chain balance of c increased by exactly amountPut.
        // Note: Put may accept value zero; rule still applies.
        assert(
            (reverted && afterBalance == beforeBalance && afterCbal == beforeCbal)
            ||
            (!reverted && afterBalance >= beforeBalance && afterCbal == beforeCbal + amountPut)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint putLock, uint putAmount, uint collectAmount, uint minSum, address logAddr) public payable {
        require(address(this).balance >= putAmount);
        // initialize config: set MinSum and Log only before Initialized
        // set MinSum and LogFile (these calls must not be reverted)
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        // mark initialized so further setup can't change MinSum/Log
        c.Initialized();

        // Read holder state before Put/Collect via public getter Acc
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        // Perform Put: send putAmount wei and lock for putLock
        c.Put{value: putAmount}(putLock);

        // Read after Put, before Collect
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midCbal = address(c).balance;

        // Now attempt Collect with collectAmount; capture whether it reverted
        bool collectReverted;
        // We must ensure this contract has enough ETH to send if Collect were to be payable (it's payable but doesn't use msg.value)
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after Collect
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // The asserted invariant: if Collect did not revert and actually decreased recorded balance by X = midBal - afterBal (>0),
        // then X equals collectAmount (i.e., recorded balance decreases exactly by the requested withdrawal),
        // and address(c).balance decreases by at least X (the contract paid out at least that much ETH).
        // We also allow cases where no change happened (e.g., collect didn't meet conditions) — then either reverted==true or balances unchanged.
        uint balDecrease = 0;
        if (midBal >= afterBal) {
            balDecrease = midBal - afterBal;
        } else {
            // impossible under normal math, but keep zero to avoid underflow in assert
            balDecrease = 0;
        }
        uint cBalDecrease = 0;
        if (midCbal >= afterCbal) {
            cBalDecrease = midCbal - afterCbal;
        } else {
            cBalDecrease = 0;
        }

        assert(
            // If Collect reverted then we make no claim about changes (allow any changes)
            (collectReverted) 
            || 
            // Otherwise (Collect did not revert): if recorded balance decreased, it must equal collectAmount;
            // and contract's ETH balance must decrease by at least that recorded decrease.
            (( !collectReverted) && ((balDecrease == 0 && cBalDecrease == 0) || (balDecrease == collectAmount && cBalDecrease >= balDecrease)))
        );
    }

    // allow receiving ETH if Collect sends funds to this contract (though in P, Collect sends to msg.sender which is this test contract)
    receive() external payable { }
}
